insert into public.content_blocks (key, value, schema_version) values
  ('ILGAN', $json${"甲":{"summary":"곧게 위로 자라는 큰 나무 같은 사람","personality":"곧고 정직하며 한번 마음먹으면 앞장서서 밀고 나가는 편이에요. 새로운 일을 시작하는 추진력과 리더십이 있어요. 다만 한번 정한 방향을 바꾸는 데 시간이 걸려 고집이 세다는 말을 들을 수 있어요.","wealth":"한 방향으로 꾸준히 키워가는 스타일이에요. 눈앞의 이익보다 장기적으로 쌓아가는 계획에 강하고, 체면 때문에 지출이 커지지 않게만 신경 쓰면 좋아요.","love":"솔직하고 든든하게 마음을 표현하는 편이에요. 상대를 이끌려는 마음이 강해서 가끔 일방적으로 보일 수 있으니, 상대의 속도도 살펴주면 관계가 더 편안해져요."},"乙":{"summary":"바람에 휘어도 꺾이지 않는 풀과 덩굴 같은 사람","personality":"부드럽고 적응력이 좋아 어떤 환경에서도 자리를 잡아요. 섬세하게 주변을 살피는 눈치가 있고 끈기도 있어요. 다만 남의 시선을 신경 쓰다 자기 마음을 뒤로 미루기 쉬워요.","wealth":"여러 방법을 유연하게 활용해 돈의 길을 찾는 스타일이에요. 사람들과의 관계에서 기회가 오는 편이라, 관계를 잘 가꾸는 것이 재물에도 도움이 돼요.","love":"다정하고 배려 깊게 상대에게 맞춰주는 편이에요. 맞춰주기만 하다 지치지 않도록 내 마음도 자주 말로 표현해보세요."},"丙":{"summary":"모두를 비추는 태양 같은 사람","personality":"밝고 활발하며 숨김없이 솔직해요. 사람들을 끌어당기는 에너지와 표현력이 있고 뒤끝이 없는 편이에요. 열정이 앞서 성급하게 결정하거나 끝맺음이 약해질 수 있어요.","wealth":"씀씀이가 시원하고 나누는 걸 즐기는 스타일이에요. 기분에 따라 지출이 커질 수 있으니 큰 결정 전에 하루 정도 여유를 두면 좋아요.","love":"감정 표현이 크고 적극적이에요. 열정적으로 다가가지만 식는 것도 빠를 수 있어서, 꾸준히 온기를 유지하는 습관이 도움이 돼요."},"丁":{"summary":"어둠을 밝히는 촛불 같은 사람","personality":"겉으로는 차분하지만 안에는 뜨거운 열정과 집중력이 있어요. 섬세하고 따뜻하며 한 가지에 깊이 몰입해요. 감정이 예민해 사소한 말에 오래 마음을 쓰기도 해요.","wealth":"필요한 곳에 정성껏 쓰고 알뜰히 챙기는 스타일이에요. 전문성을 키워 인정받을수록 수입도 안정되는 흐름이에요.","love":"은은하고 깊게 마음을 주는 편이에요. 속마음을 잘 말하지 않아 오해가 생길 수 있으니, 작은 표현을 자주 해주면 좋아요."},"戊":{"summary":"묵직하게 자리를 지키는 큰 산 같은 사람","personality":"듬직하고 신중하며 믿음직하다는 말을 자주 들어요. 여러 사람을 품는 포용력이 있어요. 변화에는 느긋해서 새 흐름에 올라타는 데 시간이 걸릴 수 있어요.","wealth":"안정적으로 모으고 지키는 데 강해요. 크게 벌리기보다 탄탄하게 쌓는 방식이 잘 맞고, 너무 보수적이지 않게 가끔은 새로운 기회도 살펴보면 좋아요.","love":"한번 마음을 주면 오래 변치 않는 편이에요. 표현이 서툴러도 행동으로 챙기는 스타일이라, 말로 한 번씩 전해주면 더 좋아요."},"己":{"summary":"곡식을 키우는 논밭 같은 사람","personality":"온화하고 세심하며 실속을 잘 챙겨요. 사람들 사이에서 조율하고 돌보는 역할을 잘해요. 걱정이 많아 마음을 앞서 쓰거나, 자기 의견을 삼키는 경우가 있어요.","wealth":"꼼꼼하게 관리하고 알뜰히 모으는 스타일이에요. 작은 것도 놓치지 않는 눈이 재산을 지키는 힘이 돼요.","love":"상대를 살뜰하게 챙기고 오래 가는 관계를 좋아해요. 상대에게 너무 맞추다 지치지 않도록 내 기준도 분명히 말해보세요."},"庚":{"summary":"단단한 바위와 쇠처럼 결단력 있는 사람","personality":"의리 있고 강직하며 옳고 그름이 분명해요. 결단력과 실행력이 좋고 위기에 강해요. 표현이 직설적이라 의도와 달리 차갑게 들릴 수 있어요.","wealth":"확실한 기준으로 정리하고 결정하는 스타일이에요. 승부처에서 과감하지만, 충동적인 큰 결정은 한 번 더 점검하면 좋아요.","love":"믿음과 의리를 중요하게 여겨요. 마음은 깊은데 표현이 투박해서, 부드러운 말 한마디가 관계에 큰 힘이 돼요."},"辛":{"summary":"잘 다듬어진 보석 같은 사람","personality":"감각이 예리하고 깔끔하며 자존심이 있어요. 완성도와 디테일에 신경 쓰고 미적 감각이 좋아요. 완벽을 바라다 스스로에게 엄격해지거나 예민해질 수 있어요.","wealth":"가치 있는 것에 투자하는 눈이 있어요. 품질을 따지는 만큼 지출도 신중하게 고르는 편이라, 자기만족과 예산의 균형을 맞추면 좋아요.","love":"취향과 기준이 분명하고 한번 마음을 열면 정성을 다해요. 상대에게 기대가 높아질 수 있으니 있는 그대로의 모습도 받아들여 보세요."},"壬":{"summary":"넓게 흘러가는 큰 강과 바다 같은 사람","personality":"생각의 스케일이 크고 지혜로우며 자유로워요. 포용력과 적응력이 좋아 어디서든 잘 흘러가요. 관심사가 넓어 집중이 흩어지거나 마무리가 느슨해질 수 있어요.","wealth":"돈의 흐름을 크게 보고 움직이는 스타일이에요. 기회를 잘 포착하지만 흐름에 휩쓸리지 않게 기본 원칙을 하나 세워두면 좋아요.","love":"자유롭고 열린 마음으로 사랑하는 편이에요. 구속받는 걸 싫어해서, 서로의 공간을 존중하면서도 마음을 자주 확인해주면 좋아요."},"癸":{"summary":"조용히 스며드는 이슬과 빗물 같은 사람","personality":"차분하고 사려 깊으며 직관이 좋아요. 조용히 관찰하며 필요한 걸 알아채는 능력이 있어요. 생각이 깊어 걱정이 많아지거나 속마음을 혼자 삭이기 쉬워요.","wealth":"신중하게 조용히 모으는 스타일이에요. 정보를 충분히 모은 뒤 움직이는 편이라 안정적이에요. 너무 재다가 기회를 놓치지 않게만 유의해요.","love":"섬세하게 상대의 마음을 헤아리고 헌신적이에요. 감정을 혼자 안고 가지 말고 솔직하게 나눌 때 관계가 더 깊어져요."}}$json$::jsonb, 1),
  ('ILJU', $json${"甲子":"겨울 물가에 선 큰 나무 — 생각이 깊고 배우며 자라는 타입","乙丑":"언 땅에 뿌리내린 풀 — 조용히 끈기 있게 버텨내는 타입","丙寅":"봄 산에 뜨는 태양 — 밝고 활동적이며 추진력이 좋은 타입","丁卯":"봄 숲의 촛불 — 따뜻하고 감성이 풍부한 타입","戊辰":"비 머금은 큰 산 — 변화를 품은 든든한 리더 타입","己巳":"햇볕 드는 논밭 — 영리하고 실속 있게 움직이는 타입","庚午":"한여름 달궈진 쇠 — 열정 속에 단련되는 승부사 타입","辛未":"여름 끝자락의 보석 — 온화하게 다듬어지는 감각파 타입","壬申":"가을 바위에서 솟는 강물 — 재치 있고 흐름을 잘 타는 타입","癸酉":"가을밤의 이슬 — 맑고 섬세하게 정리하는 타입","甲戌":"가을 언덕 위의 나무 — 책임감 있고 의리를 지키는 타입","乙亥":"물가의 풀꽃 — 자유롭고 적응력 좋은 타입","丙子":"겨울 하늘의 태양 — 차가운 환경에서도 빛을 내는 당당한 타입","丁丑":"겨울 저녁의 촛불 — 차분히 속을 채워가는 신중한 타입","戊寅":"봄 숲을 품은 산 — 도전하는 마음을 가진 듬직한 타입","己卯":"봄 꽃밭의 흙 — 부드럽게 사람을 키우는 다정한 타입","庚辰":"젖은 흙 속의 쇠 — 변화 속에서 실력을 다지는 타입","辛巳":"불 옆에서 빛나는 보석 — 총명하고 자존심이 높은 타입","壬午":"여름 햇살 아래 흐르는 강 — 활력과 지혜를 함께 가진 타입","癸未":"마른 땅을 적시는 빗물 — 배려 깊고 온화한 타입","甲申":"가을 바위 위의 나무 — 곧은 소신으로 단련되는 타입","乙酉":"가을바람 속의 풀 — 예민하고 감각이 섬세한 타입","丙戌":"가을 노을의 태양 — 따뜻하고 의리 있는 타입","丁亥":"겨울 물가의 등불 — 깊은 생각과 직관이 있는 타입","戊子":"겨울 물을 품은 산 — 안정 속에 실속을 챙기는 타입","己丑":"겨울 논밭 — 묵묵히 차곡차곡 쌓아가는 타입","庚寅":"봄 숲의 도끼 — 시작하는 힘이 강한 개척자 타입","辛卯":"봄 풀숲의 보석 — 감성적이고 예민한 완벽주의 타입","壬辰":"넓은 호수 — 스케일이 크고 가능성이 많은 타입","癸巳":"여름 초입의 이슬 — 영리하고 분위기를 잘 읽는 타입","甲午":"여름 햇살 속의 큰 나무 — 열정적이고 표현이 활발한 타입","乙未":"여름 끝 화단의 꽃 — 온순하고 조화를 잘 이루는 타입","丙申":"가을 하늘의 태양 — 재치 있고 활동 범위가 넓은 타입","丁酉":"가을밤의 촛불 — 섬세하고 세련된 감각의 타입","戊戌":"가을 큰 산 — 믿음직하고 고집도 있는 타입","己亥":"물가의 논밭 — 여유롭고 융통성 있는 타입","庚子":"겨울 물에 씻긴 쇠 — 영리하고 냉철한 타입","辛丑":"언 땅 속의 보석 — 인내하며 가치를 키우는 타입","壬寅":"봄에 풀리는 강물 — 생동감 있고 아이디어가 많은 타입","癸卯":"봄비 머금은 풀잎 — 부드럽고 감수성이 풍부한 타입","甲辰":"젖은 흙 위의 큰 나무 — 뿌리가 튼튼한 성장형 타입","乙巳":"햇살 받는 덩굴 — 영리하고 유연하게 뻗어가는 타입","丙午":"한낮의 태양 — 뜨겁고 화끈한 존재감의 타입","丁未":"여름 저녁의 촛불 — 따뜻하고 정 많은 타입","戊申":"가을 산의 바위 — 실용적이고 재주 많은 타입","己酉":"가을 들판의 흙 — 알뜰하고 정갈한 타입","庚戌":"가을 산의 쇠 — 의리 있고 강단 있는 타입","辛亥":"물에 씻긴 보석 — 맑고 자유로운 감각의 타입","壬子":"한겨울의 큰 강 — 깊고 넓은 지혜의 타입","癸丑":"겨울 눈 속의 이슬 — 조용히 견디며 준비하는 타입","甲寅":"봄 숲의 큰 나무 — 당당하게 자라나는 우직한 타입","乙卯":"봄 들판의 풀꽃 — 유연하고 사교적인 타입","丙辰":"봄비 온 뒤의 태양 — 밝고 포용력 있는 타입","丁巳":"여름 초입의 불꽃 — 집중력이 좋고 열정적인 타입","戊午":"한여름 햇볕 받는 산 — 열정을 품은 당찬 타입","己未":"여름 끝 마른 논밭 — 온화하고 고집 있는 타입","庚申":"가을 바위산 — 강단 있고 자기 주관이 뚜렷한 타입","辛酉":"가을 보석 — 자존심 높고 세련된 완성형 타입","壬戌":"가을 저수지 — 신중하고 책임감 있는 타입","癸亥":"깊은 겨울 바다의 이슬 — 직관적이고 자유로운 타입"}$json$::jsonb, 1),
  ('TEN_GODS', $json${"비견":{"hanja":"比肩","group":"비겁","meaning":"나와 같은 기운 · 동료와 자립심","today":"오늘은 나와 결이 비슷한 사람이 곁에 있어. 함께하면 든든하지만 괜한 경쟁심은 조심해!"},"겁재":{"hanja":"劫財","group":"비겁","meaning":"나와 같은 기운 · 경쟁과 추진력","today":"오늘은 승부욕이 살아나는 날이야. 욕심내서 무리하기보다 나눠 쓰는 마음이 좋아!"},"식신":{"hanja":"食神","group":"식상","meaning":"내가 만들어내는 기운 · 재능과 여유","today":"오늘은 마음이 여유롭고 표현이 술술 나오는 날이야. 하고 싶던 걸 해봐!"},"상관":{"hanja":"傷官","group":"식상","meaning":"내가 만들어내는 기운 · 자유로운 표현","today":"오늘은 톡톡 튀는 아이디어가 잘 떠올라. 말은 조금만 부드럽게 하면 더 좋아!"},"편재":{"hanja":"偏財","group":"재성","meaning":"내가 다스리는 기운 · 유동적인 재물과 기회","today":"오늘은 새로운 기회나 만남이 스치는 날이야. 지출은 한 번 더 확인하자!"},"정재":{"hanja":"正財","group":"재성","meaning":"내가 다스리는 기운 · 꾸준함과 성실","today":"오늘은 차근차근 정리하고 챙기기 좋은 날이야. 작은 성실함이 쌓일 거야!"},"편관":{"hanja":"偏官","group":"관성","meaning":"나를 다스리는 기운 · 도전과 책임","today":"오늘은 조금 긴장되는 일이 있을 수 있어. 숨 고르고 하나씩 해결하면 돼!"},"정관":{"hanja":"正官","group":"관성","meaning":"나를 다스리는 기운 · 질서와 신뢰","today":"오늘은 약속과 규칙을 지키면 신뢰가 쌓이는 날이야. 정돈된 하루를 보내봐!"},"편인":{"hanja":"偏印","group":"인성","meaning":"나를 도와주는 기운 · 직관과 독특한 배움","today":"오늘은 혼자 생각하고 배우기 좋은 날이야. 독특한 영감이 떠오를 수 있어!"},"정인":{"hanja":"正印","group":"인성","meaning":"나를 도와주는 기운 · 학문과 보호","today":"오늘은 주변의 도움과 응원이 따르는 날이야. 배우고 쉬며 마음을 채워봐!"}}$json$::jsonb, 1),
  ('ELEMENT_LACKING', $json${"wood":"목(木) 기운이 드러나지 않아요. 성장과 시작의 에너지를 의식적으로 채우면 좋아요. 새로운 배움이나 산책 같은 활동이 잘 맞을 수 있어요.","fire":"화(火) 기운이 드러나지 않아요. 열정과 표현을 꺼내는 연습이 도움이 돼요. 좋아하는 일을 소리 내어 이야기해보세요.","earth":"토(土) 기운이 드러나지 않아요. 안정감과 꾸준함을 만드는 나만의 루틴이 도움이 돼요.","metal":"금(金) 기운이 드러나지 않아요. 결단하고 마무리하는 힘을 의식해서 챙기면 좋아요.","water":"수(水) 기운이 드러나지 않아요. 여유를 갖고 생각을 정리하는 시간이 도움이 돼요."}$json$::jsonb, 1),
  ('ELEMENT_STRONG', $json${"wood":"목(木) 기운이 강해요. 성장욕과 추진력이 큰 대신 고집이 세질 수 있어요.","fire":"화(火) 기운이 강해요. 열정과 표현력이 큰 대신 성급해지기 쉬워요.","earth":"토(土) 기운이 강해요. 신중하고 안정적인 대신 변화에는 느릴 수 있어요.","metal":"금(金) 기운이 강해요. 원칙과 결단력이 큰 대신 딱딱해 보일 수 있어요.","water":"수(水) 기운이 강해요. 지혜롭고 유연한 대신 생각이 많아지기 쉬워요."}$json$::jsonb, 1),
  ('ELEMENT_BALANCED', $json$"다섯 기운이 비교적 고르게 퍼져 있어요. 한쪽으로 크게 치우치지 않은 편이에요."$json$::jsonb, 1),
  ('PILLAR_INFO', $json${"year":{"label":"년주","meaning":"조상과 어린 시절, 바깥 환경"},"month":{"label":"월주","meaning":"부모와 사회, 직업 환경"},"day":{"label":"일주","meaning":"나 자신(일간)과 배우자 자리(일지)"},"hour":{"label":"시주","meaning":"자녀와 후반기, 결과"}}$json$::jsonb, 1),
  ('YEAR_THEME', $json${"비견":{"title":"함께 걷는 동료의 해","body":"나와 비슷한 사람들과 어울릴 일이 많아지는 흐름이에요. 든든한 협력이 생기지만, 경쟁심이나 나눠야 할 몫에는 여유를 가지면 좋아요."},"겁재":{"title":"승부욕이 살아나는 해","body":"도전과 경쟁이 늘어나는 흐름이에요. 의욕은 커지지만 무리한 지출이나 욕심은 한 번 더 점검하면 좋아요."},"식신":{"title":"여유와 표현의 해","body":"마음이 편안해지고 재능을 펼치기 좋은 흐름이에요. 미뤄둔 취미나 배움을 시작해보기 좋아요."},"상관":{"title":"아이디어가 튀는 해","body":"새로운 시도와 자유로운 표현이 늘어나는 흐름이에요. 말과 행동이 직설적이 되기 쉬우니 부드럽게 전하면 더 좋아요."},"편재":{"title":"기회가 오가는 해","body":"활동 범위가 넓어지고 새로운 기회와 만남이 늘어나는 흐름이에요. 들어오고 나가는 것이 커질 수 있으니 계획을 세워 관리해보세요."},"정재":{"title":"차근차근 쌓는 해","body":"성실하게 챙기고 정리하는 만큼 결과가 따라오는 흐름이에요. 꾸준한 저축이나 계획과 잘 맞아요."},"편관":{"title":"도전과 책임의 해","body":"맡은 일과 책임이 커지고 긴장되는 순간이 생길 수 있는 흐름이에요. 한 번에 다 하기보다 우선순위를 정해 하나씩 해결해보세요."},"정관":{"title":"신뢰를 쌓는 해","body":"규칙과 약속을 지킬수록 인정받는 흐름이에요. 직장이나 조직에서 역할이 또렷해지는 해가 될 수 있어요."},"편인":{"title":"배움과 영감의 해","body":"혼자 생각하고 배우는 시간이 늘어나는 흐름이에요. 독특한 관심사가 생길 수 있어 새 분야를 공부하기 좋아요."},"정인":{"title":"도움받고 채우는 해","body":"주변의 도움과 응원이 따르고 배움에 유리한 흐름이에요. 쉬면서 마음을 채우고 공부나 자격을 준비하기 좋아요."}}$json$::jsonb, 1),
  ('MONTH_THEME', $json${"비견":{"title":"함께하면 수월한 달","body":"비슷한 목표를 가진 사람과 손발을 맞추기 좋은 한 달이에요. 혼자 끌어안기보다 나눠 맡으면 한결 가벼워져요."},"겁재":{"title":"의욕이 앞서는 달","body":"해보고 싶은 마음이 커지는 한 달이에요. 충동적인 결제나 약속은 하루만 미뤄서 다시 생각해보면 좋아요."},"식신":{"title":"느긋하게 즐기는 달","body":"마음의 여유가 생기고 먹고 쉬는 즐거움이 커지는 한 달이에요. 작은 취미를 하나 시작해보기 좋아요."},"상관":{"title":"말과 아이디어가 많아지는 달","body":"떠오르는 생각이 많고 표현하고 싶어지는 한 달이에요. 좋은 아이디어는 메모해두고, 말은 한 템포 부드럽게 전해보세요."},"편재":{"title":"바깥 활동이 늘어나는 달","body":"약속과 새로운 만남이 늘어나는 한 달이에요. 즐거운 만큼 지출도 커지기 쉬우니 이번 달 예산을 먼저 정해두면 좋아요."},"정재":{"title":"살림을 챙기는 달","body":"돈과 일정을 꼼꼼히 정리하기 좋은 한 달이에요. 미뤄둔 가계부나 서류를 정리하면 마음이 편해져요."},"편관":{"title":"긴장감이 도는 달","body":"마감이나 해야 할 일이 몰리기 쉬운 한 달이에요. 체력을 아끼면서 급한 것부터 하나씩 처리해보세요."},"정관":{"title":"성실함이 빛나는 달","body":"약속과 규칙을 지키는 모습이 눈에 띄는 한 달이에요. 맡은 일을 차근차근 마무리하면 좋은 평가로 돌아오기 쉬워요."},"편인":{"title":"혼자 파고드는 달","body":"조용히 생각하고 무언가를 깊이 알아보고 싶어지는 한 달이에요. 새로운 관심사가 생기면 가볍게 공부해보세요."},"정인":{"title":"채우고 배우는 달","body":"주변의 도움을 받기 쉽고 배움이 잘 들어오는 한 달이에요. 충분히 쉬면서 책이나 강의로 나를 채워보세요."}}$json$::jsonb, 1),
  ('DAEUN_THEME', $json${"비견":{"title":"동료와 자립의 시기","body":"나와 결이 비슷한 사람들과 함께하며 자립심을 키우는 10년이에요. 협력과 경쟁이 함께 오니 균형을 잡는 게 중요해요."},"겁재":{"title":"도전과 경쟁의 시기","body":"승부욕과 추진력이 커지는 10년이에요. 기회를 잡기 좋지만 무리한 욕심과 지출은 조심하면 좋아요."},"식신":{"title":"재능을 펼치는 시기","body":"여유 속에서 재능과 표현력이 자라는 10년이에요. 좋아하는 일을 꾸준히 쌓아가기 좋아요."},"상관":{"title":"표현과 변화의 시기","body":"새로운 시도와 자유로운 표현이 많아지는 10년이에요. 틀에 얽매이지 않는 도전이 잘 맞아요."},"편재":{"title":"활동 범위를 넓히는 시기","body":"사람과 기회가 늘어나며 활동 무대가 넓어지는 10년이에요. 크게 움직이는 만큼 관리 습관이 도움이 돼요."},"정재":{"title":"안정적으로 쌓는 시기","body":"꾸준한 노력이 결과로 이어지는 10년이에요. 생활 기반을 다지고 차곡차곡 모으기 좋아요."},"편관":{"title":"단련과 책임의 시기","body":"책임이 커지고 스스로를 단련하게 되는 10년이에요. 부담이 있을 수 있지만 그만큼 성장하는 시기가 될 수 있어요."},"정관":{"title":"질서와 인정의 시기","body":"규칙과 책임 안에서 신뢰를 쌓는 10년이에요. 안정된 자리와 역할을 만들어가기 좋아요."},"편인":{"title":"배움과 방향 전환의 시기","body":"독특한 관심사와 깊은 배움에 마음이 가는 10년이에요. 새로운 분야를 탐색하며 방향을 다듬기 좋아요."},"정인":{"title":"배우고 보호받는 시기","body":"배움과 안정, 주변의 도움이 따르는 10년이에요. 실력을 쌓고 기반을 다지기 좋아요."}}$json$::jsonb, 1),
  ('GROUP_INFO', $json${"비겁":{"meaning":"나와 같은 기운 · 자립과 경쟁","headline":"자기 힘으로 길을 여는 독립형","strong":"비겁이 강해요. 자기 주관과 독립심이 뚜렷하고 승부욕이 있어요. 고집이나 경쟁심이 앞서지 않게 주변 의견도 살펴보면 좋아요.","lacking":"비겁이 드러나지 않아요. 남에게 맞추는 편일 수 있어서, 내 목소리를 내는 연습이 도움이 돼요."},"식상":{"meaning":"내가 만들어내는 기운 · 재능과 표현","headline":"표현하고 만들어내는 창작형","strong":"식상이 강해요. 표현력과 아이디어가 풍부하고 하고 싶은 말을 잘하는 편이에요. 마무리보다 새로운 시도에 마음이 먼저 갈 수 있어요.","lacking":"식상이 드러나지 않아요. 속마음을 삼키기 쉬워서, 글이나 취미처럼 표현할 통로를 만들면 좋아요."},"재성":{"meaning":"내가 다스리는 기운 · 현실과 결과","headline":"현실을 잘 챙기는 실속형","strong":"재성이 강해요. 현실 감각이 좋고 결과를 챙기는 힘이 있어요. 성과에 마음이 쏠려 여유를 놓치지 않게 쉬어가세요.","lacking":"재성이 드러나지 않아요. 돈이나 현실적인 계획은 의식적으로 챙기면 도움이 돼요."},"관성":{"meaning":"나를 다스리는 기운 · 책임과 질서","headline":"책임감 있는 원칙형","strong":"관성이 강해요. 책임감이 크고 규칙 안에서 인정받는 편이에요. 스스로에게 너무 엄격해지지 않게 마음을 풀어주면 좋아요.","lacking":"관성이 드러나지 않아요. 얽매이는 것을 싫어하는 자유로운 편이라, 약속과 마감은 스스로 정해두면 좋아요."},"인성":{"meaning":"나를 도와주는 기운 · 배움과 안정","headline":"배우고 깊이 생각하는 학습형","strong":"인성이 강해요. 배우는 것을 좋아하고 생각이 깊으며 주변의 도움을 받는 편이에요. 생각이 길어져 행동이 늦어지지 않게 해보세요.","lacking":"인성이 드러나지 않아요. 스스로 헤쳐 나가는 힘이 있는 대신, 쉬고 배우는 시간을 일부러 챙기면 좋아요."}}$json$::jsonb, 1),
  ('GROUP_BALANCED', $json$"다섯 갈래가 고르게 있는 편이라 한쪽으로 치우치지 않은 균형형이에요."$json$::jsonb, 1),
  ('GAN_IMAGE', $json${"甲":"큰 나무","乙":"풀과 꽃","丙":"태양","丁":"촛불","戊":"큰 산","己":"논밭","庚":"바위와 쇠","辛":"보석","壬":"큰 강","癸":"이슬과 빗물"}$json$::jsonb, 1),
  ('ZHI_HAP', $json${"子丑":{"title":"자축합(子丑合)","body":"물의 기운 子와 흙의 기운 丑이 가까이 붙어 서로를 다독이며 안정을 향해 가는 관계예요. 조용히 협력하고 의지가 되는 흐름이에요.","transformsTo":"earth"},"寅亥":{"title":"인해합(寅亥合)","body":"성장하려는 寅과 새로 시작하려는 亥가 만나 함께 자라나는 관계예요. 곁에 있으면 의욕과 추진력이 살아나요.","transformsTo":"wood"},"卯戌":{"title":"묘술합(卯戌合)","body":"부드러운 卯와 단단한 戌이 만나 열정으로 타오르는 관계예요. 서로 다른 성질이 끌리며 뜨거워지는 흐름이에요.","transformsTo":"fire"},"辰酉":{"title":"진유합(辰酉合)","body":"辰의 포용력과 酉의 정교함이 만나 다듬고 매듭짓는 관계예요. 함께 있으면 마무리와 결실이 잘 이루어져요.","transformsTo":"metal"},"巳申":{"title":"사신합(巳申合)","body":"예리한 巳와 재치 있는 申이 만나 지혜와 유연함으로 바뀌는 관계예요. 서로 끌어당기며 흐름을 만들어가요.","transformsTo":"water"},"午未":{"title":"오미합(午未合)","body":"한낮의 기운 午와 늦여름의 기운 未가 만나 따뜻하게 어우러지는 관계예요. 편안하고 정이 오가는 흐름이에요.","transformsTo":"fire"}}$json$::jsonb, 1),
  ('ZHI_CHUNG', $json${"寅申":{"title":"인신충(寅申沖)","body":"성장하려는 寅과 결단하려는 申이 정면으로 부딪히는 관계예요. 움직임과 변화가 잦아지고, 새로운 길로 떠밀리듯 나아가기도 해요."},"巳亥":{"title":"사해충(巳亥沖)","body":"치밀한 巳와 자유로운 亥가 서로 다른 방향을 바라보는 관계예요. 마음이 흔들리거나 생각이 자주 바뀔 수 있어요."},"子午":{"title":"자오충(子午沖)","body":"물의 기운 子와 불의 기운 午가 정반대로 마주치는, 가장 강하게 부딪히는 관계예요. 감정의 기복이 크고 변화가 뚜렷하게 드러나요."},"卯酉":{"title":"묘유충(卯酉沖)","body":"나무의 기운 卯와 쇠의 기운 酉가 서로 깎아내듯 부딪히는 관계예요. 관계나 환경에서 정리와 변화가 함께 찾아와요."},"辰戌":{"title":"진술충(辰戌沖)","body":"두 흙의 기운이 정면으로 부딪히는 관계예요. 겉으로 잠잠해 보여도 안에서는 변화의 힘이 크게 움직이고 있어요."},"丑未":{"title":"축미충(丑未沖)","body":"두 흙의 기운이 서로 다른 방향으로 맞서는 관계예요. 안정을 찾으려는 마음과 흔들리는 상황이 함께 나타나요."}}$json$::jsonb, 1),
  ('ZHI_RELATION_NONE', $json$"이번 원국에서는 지지끼리 눈에 띄는 합이나 충이 없어요. 비교적 각자의 기운대로 자리 잡은 편이에요."$json$::jsonb, 1),
  ('PERSONALITY_BY_MONTH_GOD', $json${"비견":"사회에서는 누구에게 기대기보다 스스로 해내려는 모습이 두드러져요. 동료와 대등하게 어울리는 자리가 편하고, 내 몫과 원칙을 분명히 하는 편이에요.","겁재":"사회에서는 승부욕과 추진력이 먼저 보이는 편이에요. 경쟁이 있는 환경에서 오히려 힘이 나지만, 혼자 다 떠안으려는 마음은 조금 내려놓아도 괜찮아요.","식신":"사회에서는 여유 있고 편안한 사람으로 보이기 쉬워요. 좋아하는 일을 꾸준히 하며 실력을 쌓는 편이고, 분위기를 부드럽게 만드는 힘이 있어요.","상관":"사회에서는 재치 있고 아이디어가 많은 사람으로 보이기 쉬워요. 틀에 박힌 방식보다 새로운 방법을 찾는 데 강하고, 할 말은 하는 편이라 부드러운 표현을 곁들이면 더 빛나요.","편재":"사회에서는 발이 넓고 기회를 잘 알아보는 사람으로 보이기 쉬워요. 여러 사람과 일을 연결하는 데 능하고, 움직이는 만큼 성과가 따라오는 편이에요.","정재":"사회에서는 꼼꼼하고 성실한 사람으로 보이기 쉬워요. 계획을 세워 차근차근 해내는 데 강하고, 믿고 맡길 수 있다는 평을 듣는 편이에요.","편관":"사회에서는 강단 있고 위기에 강한 사람으로 보이기 쉬워요. 부담이 큰 자리에서 오히려 집중력이 올라가지만, 스스로를 너무 몰아붙이지 않도록 쉬는 시간을 챙겨주세요.","정관":"사회에서는 책임감 있고 믿음직한 사람으로 보이기 쉬워요. 정해진 규칙과 약속을 지키는 데서 안정감을 느끼고, 맡은 역할을 끝까지 해내려 해요.","편인":"사회에서는 독특한 시선과 깊은 생각을 가진 사람으로 보이기 쉬워요. 남들이 지나치는 부분을 파고드는 힘이 있고, 혼자 몰입할 수 있는 환경에서 실력이 잘 나와요.","정인":"사회에서는 차분하고 배움이 깊은 사람으로 보이기 쉬워요. 주변의 도움과 신뢰를 잘 얻는 편이고, 배운 것을 바탕으로 안정적으로 자리를 잡아가요."}$json$::jsonb, 1),
  ('WEALTH_BY_JAESEONG', $json${"none":"원국에 재성(재물을 뜻하는 기운)이 드러나 있지 않아요. 돈 자체를 목표로 삼기보다 실력과 경험을 쌓다 보면 따라오는 흐름에 가까워요. 들어오고 나가는 돈을 기록해두는 습관이 특히 도움이 돼요.","some":"원국에 재성이 알맞게 있어 돈을 보는 감각과 현실적인 균형이 있는 편이에요. 무리하지 않고 꾸준히 모으는 방식이 가장 잘 맞아요.","many":"원국에 재성이 여러 개 있어 돈과 기회에 대한 감각이 예민한 편이에요. 여러 일을 동시에 벌이기 쉬우니, 벌이는 것만큼 정리하고 지키는 계획도 함께 세우면 좋아요."}$json$::jsonb, 1),
  ('LOVE_BY_DAY_GOD', $json${"비견":"배우자 자리(일지)에 비견이 있어요. 친구처럼 대등하고 편한 관계를 원하는 편이라, 서로의 영역을 존중해주는 사람과 잘 맞아요.","겁재":"배우자 자리(일지)에 겁재가 있어요. 함께 도전하고 자극을 주고받는 관계에 끌리는 편이에요. 다툼이 생기면 이기려 하기보다 한 걸음 물러서는 여유가 관계를 지켜줘요.","식신":"배우자 자리(일지)에 식신이 있어요. 함께 먹고 쉬고 웃는 편안한 관계를 원하는 편이라, 자극보다 일상의 즐거움을 나눌 수 있는 사람과 잘 맞아요.","상관":"배우자 자리(일지)에 상관이 있어요. 대화가 잘 통하고 재미있는 관계를 중요하게 여기는 편이에요. 솔직한 말이 상처가 되지 않도록 표현을 한 번 다듬어주면 좋아요.","편재":"배우자 자리(일지)에 편재가 있어요. 활동적이고 새로운 경험을 함께할 수 있는 관계에 끌리는 편이에요. 즐거움이 큰 만큼 서로의 생활 리듬을 맞추는 대화가 도움이 돼요.","정재":"배우자 자리(일지)에 정재가 있어요. 성실하고 믿을 수 있는 안정적인 관계를 원하는 편이에요. 생활을 함께 꾸려가는 계획을 나누며 가까워지기 쉬워요.","편관":"배우자 자리(일지)에 편관이 있어요. 강단 있고 카리스마 있는 사람에게 끌리기 쉬워요. 관계에 긴장감이 생길 때는 솔직하게 마음을 나누는 시간이 큰 힘이 돼요.","정관":"배우자 자리(일지)에 정관이 있어요. 예의 바르고 책임감 있는 관계를 원하는 편이에요. 약속을 지키고 서로를 존중하는 모습에서 신뢰가 깊어져요.","편인":"배우자 자리(일지)에 편인이 있어요. 생각이 통하고 서로의 개성을 이해해주는 관계를 원하는 편이에요. 혼자만의 시간도 존중해주는 사람과 편안해요.","정인":"배우자 자리(일지)에 정인이 있어요. 서로 챙기고 보살펴주는 안정적인 관계를 원하는 편이에요. 받는 배려에 익숙해지지 않도록 고마움을 자주 표현하면 좋아요."}$json$::jsonb, 1),
  ('SINSAL', $json${"dohwa":{"name":"도화살","hanja":"桃花殺","title":"사람을 끄는 매력","body":"복숭아꽃처럼 사람들의 눈길을 모으는 기운이에요. 옛날에는 이성 문제를 조심하라는 뜻으로 풀었지만, 요즘은 매력과 인기, 표현력으로 봐요. 처음 만난 사람과도 금방 분위기를 만들고, 나를 드러내는 일에서 힘을 발휘하기 쉬워요."},"yeokma":{"name":"역마살","hanja":"驛馬殺","title":"움직이는 힘","body":"한곳에 머물기보다 움직이고 넓혀가는 기운이에요. 이동, 여행, 이사처럼 새로운 환경에 적응하는 힘이 좋아요. 반복되는 일상보다 활동 반경이 넓은 일에서 더 살아나는 편이에요."},"hwagae":{"name":"화개살","hanja":"華蓋殺","title":"혼자 깊어지는 시간","body":"화려한 덮개라는 뜻으로, 예술·학문·종교처럼 정신적인 세계에 끌리는 기운이에요. 혼자 생각을 정리하는 시간이 필요하고, 한 분야를 깊이 파고들어 자기만의 세계를 만드는 힘이 있어요."},"cheoneul":{"name":"천을귀인","hanja":"天乙貴人","title":"도움을 부르는 복","body":"신살 중 가장 좋은 길신으로 꼽혀요. 어려운 순간에 도와주는 사람이나 길이 나타나기 쉬운 기운이에요. 평소에 쌓은 인연이 중요한 순간에 힘이 되는 편이에요."},"munchang":{"name":"문창귀인","hanja":"文昌貴人","title":"글과 배움의 재능","body":"글, 공부, 시험, 말로 정리하는 일에 재능을 주는 기운이에요. 배운 것을 이해하기 쉽게 풀어내는 힘이 좋아서, 기록하거나 가르치는 일과 잘 맞아요."},"hongyeom":{"name":"홍염살","hanja":"紅艶殺","title":"은근한 감성과 멋","body":"감정 표현이 풍부하고 멋을 아는 기운이에요. 도화살이 밖으로 드러나는 매력이라면, 홍염살은 은근히 풍기는 분위기와 감수성에 가까워요. 꾸미는 일이나 예술적인 감각에서 재능이 드러나기 쉬워요."},"yangin":{"name":"양인살","hanja":"羊刃殺","title":"날카로운 결단력","body":"일간의 힘이 아주 강해지는 자리예요. 자기 주장이 분명하고 승부욕과 실행력이 뛰어나요. 힘이 센 만큼 부딪히는 일이 생기기 쉬우니, 한 박자 쉬고 말하는 습관이 큰 도움이 돼요."},"baekho":{"name":"백호살","hanja":"白虎殺","title":"강한 추진력","body":"기운이 세고 결단이 빠른 성향이에요. 옛날에는 사고를 조심하라는 뜻으로 무섭게 풀었지만, 요즘은 밀어붙이는 힘과 강단으로 봐요. 힘이 넘치는 만큼 쉬는 때를 정해두고 페이스를 조절하면 좋아요."},"goegang":{"name":"괴강살","hanja":"魁罡殺","title":"앞장서는 배짱","body":"북두칠성의 머리를 뜻하는 기운으로, 리더십과 배짱이 강한 성향이에요. 스스로 판단하고 앞장서는 힘이 있어 책임 있는 자리에서 빛나기 쉬워요. 고집이 세 보일 수 있으니 다른 의견을 들어보는 여유를 곁들이면 좋아요."},"gongmang":{"name":"공망","hanja":"空亡","title":"비어 있어 자유로운 자리","body":"공망은 \"비어 있다\"는 뜻으로, 그 자리의 일은 기대보다 결과가 늦게 따라오기 쉬운 기운이에요. 대신 욕심을 내려놓게 되어 정신적인 가치나 새로운 관점에 마음이 열리는 편이에요. 해당 자리의 일은 조급해하지 말고 길게 보면 좋아요."}}$json$::jsonb, 1),
  ('SINSAL_POSITION', $json${"year":"어린 시절·집안과 윗사람","month":"사회생활·일","day":"나 자신·배우자","hour":"가까운 관계·후반생"}$json$::jsonb, 1),
  ('SINSAL_REPEATED', $json$"두 자리 이상에 있어 이 기운이 더 뚜렷한 편이에요."$json$::jsonb, 1),
  ('SINSAL_NONE', $json$"두드러진 신살이 없어요. 한쪽으로 쏠린 기운 없이 무난하게 균형을 잡는 편이에요."$json$::jsonb, 1),
  ('JOHU_INTRO', $json$"조후는 태어난 계절의 온도와 습도를 맞춰주는 기운이에요. 옛 고전 《궁통보감》은 일간과 태어난 달의 조합마다 어떤 기운이 있어야 균형이 잡히는지 정리해두었어요."$json$::jsonb, 1),
  ('JOHU_SEASON', $json${"寅":{"title":"이른 봄","body":"입춘부터 경칩 전까지예요. 봄이 시작됐지만 아직 추위가 남아 있어, 땅이 채 녹지 않은 때예요."},"卯":{"title":"한창인 봄","body":"경칩부터 청명 전까지예요. 나무의 기운이 가장 왕성하게 뻗어 나가는 때예요."},"辰":{"title":"늦봄","body":"청명부터 입하 전까지예요. 봄기운이 무르익고 흙의 기운이 두터워지며, 여름으로 넘어가는 문턱이에요."},"巳":{"title":"초여름","body":"입하부터 망종 전까지예요. 햇볕이 강해지며 열기가 빠르게 올라오는 때예요."},"午":{"title":"한여름","body":"망종부터 소서 전까지예요. 불의 기운이 가장 강해 뜨겁고 메마르기 쉬운 때예요."},"未":{"title":"늦여름","body":"소서부터 입추 전까지예요. 흙이 뜨겁게 달궈진 무더위 속에서도 서늘한 기운이 조금씩 싹트는 때예요."},"申":{"title":"초가을","body":"입추부터 백로 전까지예요. 서늘한 금의 기운이 들어오며 더위가 물러나기 시작하는 때예요."},"酉":{"title":"한창인 가을","body":"백로부터 한로 전까지예요. 금의 기운이 가장 강해 공기가 맑고 단단해지는 때예요."},"戌":{"title":"늦가을","body":"한로부터 입동 전까지예요. 만물이 거둬지고 흙의 기운이 두터워지며, 겨울로 넘어가는 문턱이에요."},"亥":{"title":"초겨울","body":"입동부터 대설 전까지예요. 물의 기운이 들어오며 날이 차가워지기 시작하는 때예요."},"子":{"title":"한겨울","body":"대설부터 소한 전까지예요. 물의 기운이 가장 강하고 추위가 깊어지는 때예요."},"丑":{"title":"늦겨울","body":"소한부터 입춘 전까지예요. 추위가 가장 매서운 가운데 땅이 얼어 있는 때예요."}}$json$::jsonb, 1),
  ('JOHU_ROLE', $json${"甲":"큰 나무처럼 두꺼운 흙을 뚫어 숨통을 틔우고, 불씨를 이어주는 역할을 해요.","乙":"덩굴처럼 부드럽게 뻗어 메마른 흙에 생기를 더해줘요.","丙":"태양처럼 온기를 더해 차갑고 얼어붙은 기운을 녹여줘요.","丁":"등불처럼 차가운 기운을 밝히고, 단단한 쇠를 다듬어 쓸모 있게 만들어줘요.","戊":"둑처럼 넘치는 물을 막아 흐름을 바로잡아줘요.","己":"촉촉한 흙처럼 약한 기운이 뿌리내릴 자리를 만들어줘요.","庚":"단단한 도끼처럼 너무 무성한 나무를 다듬고, 물의 근원이 되어줘요.","辛":"맑은 보석처럼 물의 근원이 되어 물길을 맑게 이어줘요.","壬":"큰 강물처럼 뜨거운 열기를 식히고 넘치는 불을 다스려줘요.","癸":"단비처럼 메마른 기운을 촉촉하게 적셔줘요."}$json$::jsonb, 1),
  ('CAREER_BY_GROUP', $json${"비겁":{"keywords":"자립심, 실행력, 책임감","body":"비겁이 강해서 남에게 기대기보다 내 힘으로 결과를 만들어낼 때 가장 살아나는 타입이에요. 누가 정해준 길을 따라가기보다 스스로 판단하고 움직일 수 있는 일에서 의욕이 크게 올라요. 혼자서도 끝까지 해내는 뚝심이 있어 믿고 맡길 수 있다는 평을 듣기 쉽고, 뜻이 맞는 사람들과 팀을 이루면 앞장서서 분위기를 이끄는 역할도 잘해요. 다만 내 방식에 대한 확신이 강한 만큼, 다른 사람의 방식을 존중하는 여유를 곁들이면 더 넓은 무대를 함께 만들 수 있어요.","jobs":"프리랜서, 1인 창업, 운동·코칭, 현장 리더, 기술 전문직, 영업 팀장"},"식상":{"keywords":"표현력, 창의성, 손재주","body":"식상이 강해서 머릿속 생각을 말, 글, 작품, 기술로 꺼내 보일 때 가장 빛나는 타입이에요. 정해진 답을 반복하기보다 새로운 방식을 시도하고 결과물을 직접 만들어내는 일에서 보람을 느껴요. 사람들 앞에서 설명하거나 가르치는 일에도 재능이 있어, 내 생각이 누군가에게 전해질 때 큰 힘을 얻어요. 아이디어가 많은 만큼 벌여놓고 마무리가 늦어지기 쉬우니, 끝맺는 날짜를 먼저 정해두는 습관이 실력을 결과로 바꿔줘요.","jobs":"디자이너, 작가·콘텐츠 제작자, 요리사, 강사·교사, 기획자, 공예·기술직"},"재성":{"keywords":"현실 감각, 추진력, 협상력","body":"재성이 강해서 결과가 눈에 보이고 숫자로 확인되는 일에서 강점이 살아나는 타입이에요. 사람과 기회를 연결하고, 흩어진 자원을 모아 성과로 바꾸는 감각이 좋아요. 현실적인 판단이 빨라 어디에 힘을 쓰면 효과가 큰지 잘 알아보고, 협상이나 거래 자리에서도 손해 보지 않는 편이에요. 다만 여러 기회를 한꺼번에 잡으려다 힘이 분산되기 쉬우니, 가장 중요한 한두 가지에 집중하는 우선순위를 세우면 성과가 더 커져요.","jobs":"영업·마케팅, 유통·무역, 재무·회계, 투자·자산관리, 사업 운영, 부동산"},"관성":{"keywords":"책임감, 신뢰, 조직력","body":"관성이 강해서 규칙과 책임이 분명한 자리에서 믿음직하게 자리를 잡는 타입이에요. 맡은 역할을 끝까지 해내고 약속을 지키는 모습 덕분에 조직에서 신뢰를 얻기 쉬워요. 체계 안에서 차근차근 경력을 쌓아 올라가는 길과 잘 맞고, 사람과 일을 관리하고 기준을 세우는 역할에서도 능력을 보여요. 책임감이 큰 만큼 스스로에게 엄격해지기 쉬우니, 잘 해낸 일은 스스로 인정해주는 여유를 챙기면 오래 힘을 낼 수 있어요.","jobs":"공무원·공공기관, 기업 관리직, 법률·행정, 군인·경찰, 인사·총무, 품질·안전 관리"},"인성":{"keywords":"학습력, 깊이, 신중함","body":"인성이 강해서 배우고 이해하고 깊이 파고드는 일에서 가장 편안한 타입이에요. 한 분야를 꾸준히 공부해 전문성을 쌓는 데 강하고, 자격이나 지식이 실력의 바탕이 되는 일과 잘 맞아요. 주변의 도움과 신뢰를 잘 얻는 편이라 좋은 스승이나 선배를 만나면 성장 속도가 빨라져요. 생각이 깊은 만큼 시작이 늦어질 수 있으니, 준비가 덜 됐다 싶어도 작게 먼저 해보는 연습이 기회를 넓혀줘요.","jobs":"연구원, 교수·교사, 의료·보건 전문직, 상담사, 출판·편집, 전문 자격직"}}$json$::jsonb, 1),
  ('CAREER_BALANCED', $json${"keywords":"균형감, 적응력, 다재다능","body":"십신이 한쪽으로 크게 쏠리지 않아, 어느 한 분야에 묶이기보다 여러 역할에 고르게 적응하는 타입이에요. 상황에 따라 앞에 나서기도 하고 뒤에서 받쳐주기도 하는 유연함이 강점이에요. 다양한 경험을 쌓을수록 나에게 맞는 일이 또렷해지는 편이라, 관심 가는 일을 작게 여러 번 시도해보는 것이 좋아요. 여러 일을 두루 잘하는 만큼 하나의 대표 분야를 정해두면 사람들이 나를 기억하기 쉬워져요.","jobs":"기획·운영, 프로젝트 관리, 서비스업, 교육, 컨설팅, 여러 분야의 실무"}$json$::jsonb, 1),
  ('CAREER_STYLE_BY_MONTH_GOD', $json${"비견":"내 방식과 속도를 지킬 수 있는 환경에서 능률이 가장 높아요. 세세하게 지시받는 구조보다는 목표와 범위를 받고 그 안에서 스스로 계획을 세울 때 실력이 잘 나와요. 동료와는 위아래보다 대등하게 의견을 주고받는 관계가 편하고, 각자 맡은 몫이 분명할수록 갈등이 줄어요. 혼자 쌓은 노하우를 기록해 나누는 습관을 들이면, 혼자 강한 사람에서 함께 강한 사람으로 성장할 수 있어요.","겁재":"목표와 경쟁이 분명할수록 힘이 나는 편이에요. 성과에 따라 보상이 따르는 환경에서 추진력이 빛나고, 마감이 다가올수록 집중력이 올라가요. 동료와는 서로 자극을 주고받는 관계에서 실력이 늘지만, 경쟁심이 앞서면 협력의 기회를 놓칠 수 있어요. 이긴 뒤에 함께한 사람들의 몫을 챙겨주면 따르는 사람이 많아져, 더 중요한 일을 맡게 돼요.","식신":"여유를 갖고 꾸준히 실력을 쌓을 수 있는 환경에서 능률이 높아요. 급하게 몰아치는 일보다 하나를 깊이 다듬어 완성도를 높이는 일에서 만족을 느껴요. 분위기를 부드럽게 만드는 힘이 있어 동료들이 편하게 다가오고, 함께 일하는 사람들 사이에서 윤활유 역할을 잘해요. 좋아하는 일과 잘하는 일이 겹치는 지점을 찾으면 오래 지치지 않고 일할 수 있어요.","상관":"자유롭게 아이디어를 내고 시도할 수 있는 환경에서 능률이 높아요. 정해진 절차를 그대로 따르기보다 더 나은 방법을 찾아 바꾸는 일에서 보람을 느껴요. 할 말은 하는 편이라 회의에서 날카로운 의견으로 존재감을 보이는데, 말투를 한 번 다듬어 전하면 설득력이 훨씬 커져요. 변화가 많은 프로젝트나 새 서비스를 만드는 자리에서 특히 실력이 드러나요.","편재":"사람을 많이 만나고 현장을 직접 뛰는 환경에서 능률이 높아요. 한자리에 오래 앉아 있기보다 여러 곳을 오가며 기회를 찾고 연결하는 일에서 활력이 생겨요. 처음 보는 사람과도 금방 관계를 트는 편이라, 대외 업무나 네트워크가 중요한 일에서 강점이 있어요. 벌여놓은 일이 많아지기 쉬우니, 주기적으로 일정과 할 일을 정리하는 시간을 따로 두면 좋아요.","정재":"계획과 절차가 분명하고 꼼꼼함이 인정받는 환경에서 능률이 높아요. 숫자와 일정, 자원을 차근차근 관리하며 실수를 줄이는 데 강점이 있어요. 믿고 맡길 수 있는 사람으로 통하기 쉬워, 시간이 갈수록 중요한 일을 맡게 되는 편이에요. 안정을 중시하는 만큼 새로운 시도는 작은 단위로 먼저 해보면, 부담 없이 경험의 폭을 넓힐 수 있어요.","편관":"책임이 크고 긴장감 있는 자리에서 오히려 집중력이 올라가는 편이에요. 문제가 생겼을 때 앞에 나서서 정리하는 해결사 역할에 강하고, 위기 상황에서 결단이 빨라요. 기준과 원칙이 분명한 조직에서 리더십을 발휘하기 좋아요. 다만 스스로를 몰아붙이기 쉬워, 일이 몰리는 시기에는 쉬는 시간을 일정에 미리 넣어두는 게 좋아요.","정관":"역할과 규칙이 분명한 조직에서 안정감을 느끼며 능률이 높아져요. 체계 안에서 신뢰를 쌓아 차근차근 올라가는 길이 잘 맞고, 정해진 약속과 마감을 잘 지켜요. 예의 바르고 성실한 사람으로 인정받기 쉬워 평판이 쌓일수록 기회가 늘어나요. 원칙을 중시하는 만큼 갑작스러운 변화에는 부담을 느낄 수 있으니, 변화가 예상될 때는 미리 정보를 모아두면 마음이 편해요.","편인":"혼자 깊이 몰입할 수 있는 조용한 환경에서 능률이 높아요. 남들이 지나치는 부분을 파고들어 독창적인 답을 찾아내는 데 강점이 있어요. 잦은 회의보다는 자료를 보고 정리하는 시간이 충분할 때 실력이 잘 드러나요. 생각을 혼자만 간직하기 쉬우니, 정리한 내용을 짧게라도 공유하는 습관을 들이면 능력을 인정받기 쉬워져요.","정인":"배우고 성장할 수 있는 환경, 좋은 선배나 스승이 있는 곳에서 능률이 높아요. 체계적으로 지식을 쌓아 전문성을 키우는 데 강하고, 자격이나 학위가 도움이 되는 길과 잘 맞아요. 주변의 신뢰를 얻는 차분함이 있어 조언을 구하러 오는 사람이 많아지는 편이에요. 준비에 시간을 많이 쓰는 만큼, 배운 것을 바로 써볼 기회를 일부러 만들면 성장 속도가 빨라져요."}$json$::jsonb, 1),
  ('CAREER_TIP_BY_LACKING', $json${"비겁":"비겁(나를 지지하는 기운)이 원국에 드러나 있지 않아서, 혼자 결정하고 밀고 나가야 하는 일은 부담이 될 수 있어요. 믿을 만한 동료나 멘토와 함께 의논하는 구조를 만들면 훨씬 힘이 덜 들어요. 작은 결정부터 스스로 정해보는 연습도 자신감을 키워줘요.","식상":"식상(표현과 재능을 뜻하는 기운)이 원국에 드러나 있지 않아서, 생각을 밖으로 꺼내 보이는 일은 연습이 필요할 수 있어요. 기록하거나 짧게 발표하는 습관을 들이면 실력이 제대로 평가받는 데 도움이 돼요. 결과물을 눈에 보이게 정리해두는 것도 좋은 방법이에요.","재성":"재성(재물과 현실 감각을 뜻하는 기운)이 원국에 드러나 있지 않아서, 일 자체에는 몰입해도 돈 계산이나 계약 조건은 뒤로 미루기 쉬워요. 단가 정하기, 정산, 계약서 확인 같은 실무는 꼼꼼한 동료나 도구의 도움을 받거나, 일을 시작하기 전에 체크리스트로 먼저 정해두면 좋아요.","관성":"관성(규칙과 책임을 뜻하는 기운)이 원국에 드러나 있지 않아서, 정해진 틀이나 마감이 없으면 일이 느슨해지기 쉬워요. 스스로 마감일을 정하고 진행 상황을 누군가와 공유하면 꾸준함이 훨씬 좋아져요.","인성":"인성(배움과 안정을 뜻하는 기운)이 원국에 드러나 있지 않아서, 깊이 준비하기보다 부딪히며 배우는 편이에요. 일이 익숙해질 때쯤 관련 공부나 자격을 한 번 정리해두면, 경험이 탄탄한 전문성으로 바뀌어요."}$json$::jsonb, 1)
